'use strict';
(()=>{
 const world=window.StoryWorld,$=id=>document.getElementById(id),board=$('world-board'),symbols={tree:'🌳',mountain:'⛰️',water:'💧',flower:'🌸',home:'🏡',road:'🟫'};
 let editing=false,tool='move',map,drag=null,pathStart=null,history=[];
 function status(text){$('maker-status').textContent=text}
 function remember(){history.push(JSON.stringify(map));if(history.length>25)history.shift();$('map-undo').disabled=false}
 function commit(){try{world.updateMap(map);status(window.FolderSave?.enabled?'Map updated · saving to the game folder.':'Map saved in this browser.');document.dispatchEvent(new Event('worldchange'))}catch(e){status('Could not save map: '+e.message);render()}}
 function point(e){const r=board.getBoundingClientRect();return {x:Math.max(30,Math.min(970,Math.round((e.clientX-r.left)/r.width*1000))),y:Math.max(30,Math.min(570,Math.round((e.clientY-r.top)/r.height*600)))}}
 function path(from,to){const a=map.nodes.find(n=>n.id===from),b=map.nodes.find(n=>n.id===to);if(!a||!b)return '';return `M ${a.x} ${a.y} C ${a.x} ${(a.y+b.y)/2}, ${b.x} ${(a.y+b.y)/2}, ${b.x} ${b.y}`}
 function drawPaths(){const svg=$('world-paths');svg.replaceChildren();const ns='http://www.w3.org/2000/svg',defs=document.createElementNS(ns,'defs'),marker=document.createElementNS(ns,'marker');marker.id='world-arrow';for(const [k,v]of Object.entries({viewBox:'0 0 10 10',refX:'28',refY:'5',markerWidth:'7',markerHeight:'7',orient:'auto'}))marker.setAttribute(k,v);const arrow=document.createElementNS(ns,'path');arrow.setAttribute('d','M 0 0 L 10 5 L 0 10 z');arrow.setAttribute('fill','#7a8751');marker.append(arrow);defs.append(marker);svg.append(defs);
  map.links.forEach(l=>{const p=document.createElementNS(ns,'path');p.setAttribute('d',path(l.from,l.to));p.setAttribute('class','world-path');p.setAttribute('marker-end','url(#world-arrow)');if(editing&&tool==='erase'){p.setAttribute('tabindex','0');p.setAttribute('role','button');p.setAttribute('aria-label','Remove this connecting path');const remove=e=>{e.stopPropagation();remember();map.links=map.links.filter(x=>x!==l);map.customPaths=true;commit();render()};p.onclick=remove;p.onkeydown=e=>{if(e.key==='Delete'||e.key==='Enter'){e.preventDefault();remove(e)}}}svg.append(p)})
 }
 function render(){if(!world.get())return;if(!drag)map=world.get().map;board.classList.toggle('editing',editing);$('maker-tools').hidden=!editing;$('toggle-maker').textContent=editing?'✓ Done building':'✎ Build your world';$('map-undo').disabled=!history.length;
  const image=$('map-reference');image.hidden=!map.reference;if(map.reference)image.src=map.reference;
  $('world-nodes').replaceChildren();$('world-scenery').replaceChildren();drawPaths();
  const w=world.get();map.nodes.forEach(n=>{const chapter=w.levels.find(c=>c.id===n.id),i=w.levels.findIndex(c=>c.id===n.id),b=document.createElement('button');b.className='world-node'+(chapter.complete?' complete':'')+(pathStart===n.id?' path-start':'');b.dataset.node=n.id;b.style.left=n.x/10+'%';b.style.top=n.y/6+'%';b.setAttribute('aria-label',(editing?'Move or connect ':'Play ')+chapter.level.title);const icon=document.createElement('strong');icon.textContent=chapter.complete?'★':i+1;const name=document.createElement('span');name.textContent=chapter.level.title;b.append(icon,name);b.onclick=e=>{e.stopPropagation();if(!editing){goTo('index.html?level='+encodeURIComponent(n.id)+'&mode=play');return}if(tool==='path'){if(!pathStart){pathStart=n.id;status('Now choose the level this path leads to.');render()}else if(pathStart!==n.id){if(!map.links.some(l=>l.from===pathStart&&l.to===n.id)){remember();map.links.push({from:pathStart,to:n.id});map.customPaths=true;commit()}pathStart=null;render()}}};
   b.onkeydown=e=>{if(!editing||tool!=='move'||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();remember();const step=e.shiftKey?20:5;n.x=Math.max(30,Math.min(970,n.x+(e.key==='ArrowRight'?step:e.key==='ArrowLeft'?-step:0)));n.y=Math.max(30,Math.min(570,n.y+(e.key==='ArrowDown'?step:e.key==='ArrowUp'?-step:0)));commit();render();board.querySelector('[data-node="'+CSS.escape(n.id)+'"]')?.focus()};$('world-nodes').append(b)});
  map.decorations.forEach(d=>{const b=document.createElement('button');b.className='world-scenery-item';b.textContent=symbols[d.kind];b.dataset.decoration=d.id;b.style.left=d.x/10+'%';b.style.top=d.y/6+'%';b.setAttribute('aria-label',d.kind);b.tabIndex=editing?0:-1;b.onclick=e=>{e.stopPropagation();if(editing&&tool==='erase'){remember();map.decorations=map.decorations.filter(x=>x.id!==d.id);commit();render()}};$('world-scenery').append(b)})
 }
 $('toggle-maker').onclick=()=>{editing=!editing;pathStart=null;render();status(editing?'Drag level markers. Add scenery or connect two levels with a path.':'Choose a level marker to start its chapter.')};
 document.querySelectorAll('[data-map-tool]').forEach(b=>b.onclick=()=>{tool=b.dataset.mapTool;pathStart=null;document.querySelectorAll('[data-map-tool]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));render();status(tool==='path'?'Choose the starting level, then the next level. Arrows show the story direction.':tool==='erase'?'Click scenery or a path to remove it. Levels stay safe.':tool==='move'?'Drag a level or scenery to move it. Arrow keys move a focused level marker.':'Click the map to place '+tool+'.')});
 board.onpointerdown=e=>{if(!editing||tool!=='move')return;const target=e.target.closest('[data-node],[data-decoration]');if(!target)return;const item=target.dataset.node?map.nodes.find(n=>n.id===target.dataset.node):map.decorations.find(n=>n.id===target.dataset.decoration);remember();drag={item,target,pointer:e.pointerId};board.setPointerCapture(e.pointerId);e.preventDefault()};
 board.onpointermove=e=>{if(!drag)return;Object.assign(drag.item,point(e));drag.target.style.left=drag.item.x/10+'%';drag.target.style.top=drag.item.y/6+'%';drawPaths()};
 const endDrag=()=>{if(!drag)return;drag=null;commit();render()};board.onpointerup=endDrag;board.onpointercancel=endDrag;
 board.onclick=e=>{if(!editing||e.target.closest('[data-node],[data-decoration]')||!symbols[tool])return;if(map.decorations.length>=300){status('This world has room for 300 scenery pieces.');return}remember();map.decorations.push({id:crypto.randomUUID(),kind:tool,...point(e)});commit();render()};
 $('map-undo').onclick=()=>{if(!history.length)return;map=JSON.parse(history.pop());commit();render()};
 $('clear-scenery').onclick=()=>{if(!confirm('Remove the scenery? Your levels, paths, and drawing will stay.'))return;remember();map.decorations=[];commit();render()};
 $('map-reference-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>12*1024*1024)throw Error('Choose a PNG, JPG, or WebP photo under 12 MB.');const url=URL.createObjectURL(file);let image;try{image=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(Error('That image could not be opened.'));i.src=url})}finally{URL.revokeObjectURL(url)}const canvas=document.createElement('canvas'),scale=Math.min(1,1400/image.width,900/image.height);canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/jpeg',.8);if(data.length>1500000)throw Error('Please choose a smaller photo.');remember();map.reference=data;commit();render();status('Your drawing is on the map! Drag the level markers into place.')}catch(err){status(err.message)}finally{e.target.value=''}};
 $('remove-reference').onclick=()=>{remember();map.reference=null;commit();render()};
 document.addEventListener('worldchange',()=>{if(!drag)render()});
 // Another window saved the story: older undo steps would bring back its old map, so start fresh.
 document.addEventListener('storychange',()=>{history=[];pathStart=null;if(!drag)render()});try{render()}catch(e){status('World Maker could not open: '+e.message)}
})();
